<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{ChevronRight,Search}from'@lucide/vue';import{api,apiError,unpack}from'@/services/api';import type{EvaluationResult}from'@/types';import StatusPill from'@/components/StatusPill.vue';import{useLocaleStore}from'@/stores/locale'
const locale=useLocaleStore(),items=ref<EvaluationResult[]>([]),loading=ref(true),error=ref(''),query=ref(''),review=ref('all');const filtered=computed(()=>items.value.filter(r=>(review.value==='all'||(review.value==='adjusted')===!!r.adjusted)&&`${r.caseTitle} ${r.studentName}`.toLowerCase().includes(query.value.toLowerCase())));onMounted(async()=>{try{items.value=unpack(await api.getResults())}catch(e){error.value=apiError(e)}finally{loading.value=false}})
</script>
<template><div class="page"><header class="page-header"><div><div class="page-eyebrow">{{locale.t('Assessment review')}}</div><h1>{{locale.t('Student results')}}</h1><p class="subtitle">{{locale.t('Inspect complete transcripts, evidence and AI-generated formative assessments.')}}</p></div></header><div class="filter-row"><div class="field" style="position:relative"><Search :size="16" style="position:absolute;left:12px;top:14px;color:#84918c"/><input v-model="query" class="input" style="padding-left:36px" :placeholder="locale.t('Search results…')"></div><select v-model="review" class="select"><option value="all">{{locale.t('All reviews')}}</option><option value="adjusted">{{locale.t('Educator adjusted')}}</option><option value="unadjusted">{{locale.t('AI score only')}}</option></select></div><div v-if="error" class="alert alert--error">{{error}}</div><div v-if="loading" class="loading"><div class="spinner"></div></div><div v-else class="card table-wrap"><table class="data-table"><thead><tr><th>{{locale.t('Student')}}</th><th>{{locale.t('Case')}}</th><th>{{locale.t('Completed')}}</th><th>{{locale.t('Score')}}</th><th>{{locale.t('Level')}}</th><th>{{locale.t('Review')}}</th><th></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.studentName}}</td><td><RouterLink :to="`/faculty/results/${r.id}`">{{r.caseTitle}}</RouterLink></td><td>{{new Date(r.createdAt).toLocaleString('en-AU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}}</td><td><strong>{{r.teacherScore??r.score}}</strong> / 100</td><td><StatusPill :value="r.level"/></td><td><StatusPill :value="r.adjusted?'Adjusted':'AI assessed'"/></td><td><RouterLink :to="`/faculty/results/${r.id}`"><ChevronRight :size="17"/></RouterLink></td></tr></tbody></table><div v-if="!filtered.length" class="empty"><Search/><h3>{{locale.t('No matching results')}}</h3><p>{{locale.t('Completed, evaluated attempts will appear here.')}}</p></div></div></div></template>
